---@field customConstraintParent? string Optional. Resource the constraint is attached to. Example: "organization/987654"

---@alias gcp.policysimulator_v1.GoogleCloudPolicysimulatorV1OrgPolicyOverlayCustomConstraintOverlayList gcp.policysimulator_v1.GoogleCloudPolicysimulatorV1OrgPolicyOverlayCustomConstraintOverlay[]

